node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { LineReader, readLines } from './src/lines.mjs';
const encoder = new TextEncoder();
const text = 'A💩\r\n\nB\rC\r';
const bytes = encoder.encode(text);
const chunks = Array.from(bytes, byte => Uint8Array.of(byte));
assert.deepEqual(await readLines(chunks), ['A💩', '', 'B\rC\r']);
assert.deepEqual(await readLines([encoder.encode('first\n\n')]), ['first', '']);
const reader = new LineReader();
assert.deepEqual(reader.feed(Uint8Array.of(0xe2)), []);
assert.deepEqual(reader.feed(Uint8Array.of(0x82)), []);
assert.deepEqual(reader.end(), ['�']);
const malformed = Uint8Array.of(0xe2, 0x28, 0xa1, 0x0a);
assert.deepEqual(await readLines(Array.from(malformed, byte => Uint8Array.of(byte))), [new TextDecoder().decode(malformed).slice(0, -1)]);
console.log('Additional streaming UTF-8 and line contract checks passed');
EOF

